import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.DqVSm8kp.js";const n="/llmxray/docs/educators/benchmark-radar.svg",s="/llmxray/docs/educators/confidence-calibration.svg",i="/llmxray/docs/educators/thinking-vs-standard.svg",b=JSON.parse('{"title":"Module 7: How Do Models Compare?","description":"","frontmatter":{},"headers":[],"relativePath":"en/community/educators/module-7.md","filePath":"en/community/educators/module-7.md"}'),l={name:"en/community/educators/module-7.md"};function c(d,e,h,m,u,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="module-7-how-do-models-compare" tabindex="-1">Module 7: How Do Models Compare? <a class="header-anchor" href="#module-7-how-do-models-compare" aria-label="Permalink to &quot;Module 7: How Do Models Compare?&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>The Scientist</strong> — Design experiments, measure results, draw conclusions</p><p><strong>Duration:</strong> 90 min | <strong>Difficulty:</strong> Advanced | <strong>Prerequisite:</strong> <a href="./module-3.html">Module 3</a>, <a href="./module-5.html">Module 5</a></p></div><h2 id="the-aha-moment" tabindex="-1">The Aha Moment <a class="header-anchor" href="#the-aha-moment" aria-label="Permalink to &quot;The Aha Moment&quot;">​</a></h2><blockquote><p>No model is universally best. A model that excels at science reasoning may fail at truthfulness. A fast model may beat a slow one on simple tasks. Benchmarks don&#39;t tell you which model is &quot;better&quot; — they tell you which model is better <em>at what</em>.</p></blockquote><p>This module transforms students from passive consumers of leaderboard rankings into active experimenters who design their own evaluations. By running controlled benchmarks and side-by-side comparisons in LLMxRay, students discover that model selection is always a tradeoff — and that the &quot;best&quot; model depends entirely on the task, the constraints, and the definition of success.</p><p>The scientific method applies directly: form a hypothesis (&quot;the larger model will be more accurate&quot;), design an experiment (run the same benchmark on both), collect data (accuracy, confidence, latency), and draw conclusions. Sometimes the hypothesis holds. Sometimes a 1B-parameter model outperforms an 8B model on a specific category. That surprise is the lesson.</p><hr><h2 id="conceptual-background" tabindex="-1">Conceptual Background <a class="header-anchor" href="#conceptual-background" aria-label="Permalink to &quot;Conceptual Background&quot;">​</a></h2><h3 id="why-compare-models" tabindex="-1">Why compare models? <a class="header-anchor" href="#why-compare-models" aria-label="Permalink to &quot;Why compare models?&quot;">​</a></h3><p>Different models have different strengths. This seems obvious, but leaderboard culture encourages a single-number ranking that obscures the reality: model selection is multidimensional.</p><p>Size is not everything. A well-trained 7B model can beat a poorly-trained 13B model on specific tasks. A model fine-tuned for code may dominate HumanEval but stumble on commonsense reasoning. A model optimized for instruction-following may be worse at creative writing than a base model with the same parameter count.</p><p>The dimensions that matter depend on your use case:</p><ul><li><strong>Speed</strong> — A chatbot needs sub-second latency. A batch analysis pipeline can wait.</li><li><strong>Accuracy</strong> — A medical assistant needs near-perfect factual accuracy. A brainstorming tool can tolerate creative leaps.</li><li><strong>Context length</strong> — Summarizing a 50-page document requires a large context window. A Q&amp;A bot may only need 2K tokens.</li><li><strong>Tool support</strong> — An agentic workflow needs reliable function calling. A conversational tutor does not.</li><li><strong>Calibration</strong> — A model that knows what it doesn&#39;t know is safer than one that&#39;s confidently wrong.</li></ul><p>Comparison is not about crowning a winner. It&#39;s about understanding the tradeoff space so you can make an informed selection.</p><h3 id="what-benchmarks-actually-measure" tabindex="-1">What benchmarks actually measure <a class="header-anchor" href="#what-benchmarks-actually-measure" aria-label="Permalink to &quot;What benchmarks actually measure&quot;">​</a></h3><p>Each benchmark tests a narrow slice of capability. Understanding what each benchmark measures — and what it does not — is essential for interpreting results.</p><table tabindex="0"><thead><tr><th>Benchmark</th><th>What it tests</th><th>Format</th><th>Example</th></tr></thead><tbody><tr><td><strong>ARC</strong></td><td>Science reasoning (grade-school to college)</td><td>Multiple-choice (4 options)</td><td>&quot;Which property of a mineral can be determined just by looking at it?&quot;</td></tr><tr><td><strong>MMLU-Pro</strong></td><td>Broad academic knowledge across 50+ domains</td><td>Multiple-choice (10 options)</td><td>Questions spanning STEM, humanities, social sciences, professional fields</td></tr><tr><td><strong>HellaSwag</strong></td><td>Commonsense completion (physical/social intuition)</td><td>Multiple-choice (4 options)</td><td>&quot;A woman is cooking pasta. She drains the water and...&quot;</td></tr><tr><td><strong>GSM8K</strong></td><td>Grade-school math with multi-step reasoning</td><td>Multiple-choice (numerical)</td><td>&quot;If a train travels 60 mph for 2.5 hours, then 40 mph for 1.5 hours...&quot;</td></tr><tr><td><strong>TruthfulQA</strong></td><td>Resistance to popular misconceptions</td><td>Multiple-choice (varies)</td><td>&quot;Can you see the Great Wall of China from space?&quot;</td></tr></tbody></table><p><img src="'+n+'" alt="Benchmark Radar"></p><p>A single aggregate score hides category-level variation. A model scoring 65% on ARC might score 85% on physics questions but only 40% on biology. MMLU-Pro&#39;s 50+ domains mean a model can excel in law and fail in chemistry — and the average conceals both. Always look at per-category breakdowns.</p><div class="warning custom-block"><p class="custom-block-title">Benchmarks are not report cards</p><p>A benchmark score tells you how well a model performs on a specific test set under specific conditions. It does not tell you how the model will perform on your task, with your data, under your constraints. Benchmarks are a starting point for comparison, not a final verdict.</p></div><h3 id="the-confidence-calibration-problem" tabindex="-1">The confidence calibration problem <a class="header-anchor" href="#the-confidence-calibration-problem" aria-label="Permalink to &quot;The confidence calibration problem&quot;">​</a></h3><p>A model can be 90% accurate but poorly <strong>calibrated</strong> — meaning its confidence scores do not correlate with its actual correctness. This is one of the most important and least discussed aspects of model evaluation.</p><p>LLMxRay measures confidence using <strong>real logprobs</strong> obtained via SSE streaming through the OpenAI-compatible <code>/v1/chat/completions</code> endpoint. This is not a simulation — these are the actual probability distributions the model computes over its vocabulary at each token position.</p><p><strong>Calibration</strong> means: when a model says it&#39;s 80% confident, is it correct roughly 80% of the time? A perfectly calibrated model would produce a diagonal line on a confidence-vs-accuracy plot. In practice, most models are <strong>overconfident</strong> — they assign high probabilities even when they&#39;re wrong.</p><p><img src="'+s+'" alt="Confidence Calibration"></p><p>The <strong>confidence vs accuracy scatter plot</strong> in LLMxRay&#39;s BenchmarkResultsPanel reveals calibration quality at a glance:</p><ul><li>Points clustered along the diagonal = well-calibrated</li><li>Points above the diagonal = underconfident (conservative but safe)</li><li>Points below the diagonal = overconfident (dangerous — the model sounds sure but is wrong)</li></ul><p><strong>Calibration error</strong> is the average gap between confidence and accuracy across confidence bins. A model with 85% accuracy and 92% average confidence has a calibration error of 7 percentage points. That gap matters: it means you cannot trust the model&#39;s self-reported certainty.</p><h3 id="thinking-models-vs-standard-models" tabindex="-1">Thinking models vs standard models <a class="header-anchor" href="#thinking-models-vs-standard-models" aria-label="Permalink to &quot;Thinking models vs standard models&quot;">​</a></h3><p>Some models — DeepSeek-R1, QwQ, and others in the &quot;reasoning&quot; family — use explicit <strong>chain-of-thought reasoning</strong> before producing their final answer. They wrap their internal deliberation in <code>&lt;think&gt;</code> blocks, working through the problem step by step before committing to a response.</p><p><img src="'+i+'" alt="Thinking vs Standard Models"></p><p>In LLMxRay, this distinction has concrete consequences:</p><ul><li><strong>Dynamic token budgets</strong>: Thinking models receive a budget of <strong>2048 tokens</strong> (to accommodate the reasoning trace), while standard models receive <strong>64 tokens</strong> (enough for a multiple-choice answer). This prevents thinking models from being penalized for their verbose reasoning process.</li><li><strong>Visible thinking</strong>: During benchmark runs, the BenchmarkLiveView shows the <code>&lt;think&gt;</code> block content streaming in real time. You can watch the model reason through each question — sometimes correctly, sometimes going down a wrong path and correcting itself.</li><li><strong>Speed vs accuracy tradeoff</strong>: Thinking models are significantly slower (often 5-10x) because they generate hundreds of reasoning tokens before answering. But on reasoning-heavy benchmarks like GSM8K and ARC, they often achieve substantially higher accuracy.</li></ul><p>The key insight is that &quot;thinking&quot; is not free. A thinking model that takes 15 seconds per question may be impractical for a real-time chatbot, even if its accuracy is 20 points higher. The right choice depends on whether your application can afford the latency.</p><div class="warning custom-block"><p class="custom-block-title">Token budget affects results</p><p>If you run a thinking model with a standard-model token budget (64 tokens), the reasoning trace will be truncated, and accuracy will drop dramatically. LLMxRay detects model capabilities automatically and assigns the appropriate budget, but be aware of this when interpreting results from other tools.</p></div><h3 id="beyond-benchmarks-real-world-comparison" tabindex="-1">Beyond benchmarks: real-world comparison <a class="header-anchor" href="#beyond-benchmarks-real-world-comparison" aria-label="Permalink to &quot;Beyond benchmarks: real-world comparison&quot;">​</a></h3><p>Benchmarks test multiple-choice performance under controlled conditions. Real tasks are open-ended, ambiguous, and subjective. A model that aces ARC might produce lifeless prose. A model that scores poorly on MMLU-Pro might be an excellent creative writing partner.</p><p>LLMxRay&#39;s <strong>Compare page</strong> bridges this gap. It lets you send the same prompt to multiple models — or the same model with different settings — and see the results side by side.</p><p>Key comparison features:</p><ul><li><strong>ComparisonGrid</strong>: See outputs from up to four model configurations simultaneously, with synchronized scrolling.</li><li><strong>ComparisonDiffView</strong>: Word-level diffs highlight exactly what changed between two outputs. A single temperature change can transform a response from formal to colloquial.</li><li><strong>ComparisonMetricsBar</strong>: Latency, token count, and throughput for each configuration, displayed as comparative bars.</li><li><strong>Temperature Sweep preset</strong>: Automatically runs the same prompt at temperatures 0.2, 0.7, and 1.2, isolating the effect of randomness on output quality.</li><li><strong>Deterministic Pair preset</strong>: Runs two configurations with the same seed, ensuring that any differences are due to the variable you changed (model, system prompt, temperature) and not random sampling.</li></ul><p>This is where science meets craft. Benchmarks give you numbers. Comparisons give you intuition.</p><hr><h2 id="hands-on-exercises" tabindex="-1">Hands-On Exercises <a class="header-anchor" href="#hands-on-exercises" aria-label="Permalink to &quot;Hands-On Exercises&quot;">​</a></h2><h3 id="exercise-1-the-benchmark-showdown" tabindex="-1">Exercise 1: The benchmark showdown <a class="header-anchor" href="#exercise-1-the-benchmark-showdown" aria-label="Permalink to &quot;Exercise 1: The benchmark showdown&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Open the <strong>Benchmark</strong> page in LLMxRay</li><li>In the <strong>BenchmarkConfigurator</strong>, select a small model (e.g., <code>llama3.2:1b</code>) and a larger model (e.g., <code>llama3.1:8b</code>)</li><li>Select the <strong>ARC</strong> benchmark suite</li><li>Run the benchmark on both models (you can run them sequentially or in parallel if your hardware allows)</li><li>While each benchmark runs, watch the <strong>BenchmarkLiveView</strong> closely: <ul><li>Real-time progress percentage</li><li>Green/red indicators for correct/incorrect answers</li><li>Category progress bars filling as questions complete</li><li>For thinking models, the <code>&lt;think&gt;</code> block streaming live</li></ul></li><li>After both runs complete, compare the results in the <strong>BenchmarkResultsPanel</strong>: <ul><li><strong>Overall accuracy</strong>: Which model scored higher? By how much?</li><li><strong>Per-category breakdown</strong>: Are there categories where the small model matches or beats the large one?</li><li><strong>Average confidence</strong>: Which model is more confident overall? Is higher confidence correlated with higher accuracy?</li><li><strong>Latency</strong>: How much faster is the small model? Calculate the accuracy-per-second ratio.</li></ul></li></ol><p><strong>What you&#39;ll discover:</strong></p><p>The larger model will likely win on overall accuracy — but the margin may be smaller than you expect. On some categories (especially ones requiring pattern matching rather than deep reasoning), the small model may hold its own. And the small model will almost certainly be faster, sometimes by 5-10x. This is the core tradeoff: is the accuracy gain worth the latency cost for your specific application?</p><hr><h3 id="exercise-2-the-category-heatmap" tabindex="-1">Exercise 2: The category heatmap <a class="header-anchor" href="#exercise-2-the-category-heatmap" aria-label="Permalink to &quot;Exercise 2: The category heatmap&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Run <strong>MMLU-Pro</strong> on a model of your choice (this benchmark has 50+ categories, so it takes longer — be patient)</li><li>Run <strong>ARC</strong> on the same model if you haven&#39;t already</li><li>Open the <strong>BenchmarkComparisonLedger</strong></li><li>Examine the <strong>radar chart</strong>: each axis represents a benchmark or category, with scores shown as percentile ranks. Notice the shape — is it roughly circular (balanced) or spiky (specialist)?</li><li>Examine the <strong>heatmap</strong> (models x categories): each cell is color-coded from red (low accuracy) to green (high accuracy)</li><li>Answer these questions: <ul><li>Which 3 categories does the model perform best in?</li><li>Which 3 categories does it perform worst in?</li><li>Is there a pattern? Do STEM categories cluster together? Do humanities?</li><li>Compare the ARC science categories with MMLU-Pro science categories. Do they correlate?</li></ul></li></ol><p><strong>What you&#39;ll discover:</strong></p><p>Models are not uniformly capable. The heatmap makes this viscerally clear — a single model can range from 90% in one category to 30% in another. Categories that require factual recall (history dates, geography) often score differently from categories requiring reasoning (physics, logic). The radar chart&#39;s irregular shape is the visual proof that no single number captures a model&#39;s capabilities.</p><div class="warning custom-block"><p class="custom-block-title">MMLU-Pro is large</p><p>MMLU-Pro contains thousands of questions across 50+ domains. A full run can take 30-60 minutes depending on your hardware and model speed. For classroom use, consider running a subset of categories or using the quick-run option if available.</p></div><hr><h3 id="exercise-3-confidence-calibration-analysis" tabindex="-1">Exercise 3: Confidence calibration analysis <a class="header-anchor" href="#exercise-3-confidence-calibration-analysis" aria-label="Permalink to &quot;Exercise 3: Confidence calibration analysis&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>From your benchmark results (Exercise 1 or 2), open the <strong>BenchmarkResultsPanel</strong> for each model</li><li>Locate the <strong>Confidence vs Accuracy scatter plot</strong></li><li>For each model, analyze: <ul><li>Are high-confidence answers (&gt;80% logprob) more often correct than low-confidence answers (&lt;50%)?</li><li>Where do most points fall relative to the diagonal line?</li><li>Is the model overconfident (points below diagonal) or underconfident (points above)?</li></ul></li><li>Calculate the <strong>calibration error</strong> for each model: <ul><li>Group answers into confidence bins (e.g., 0-20%, 20-40%, 40-60%, 60-80%, 80-100%)</li><li>For each bin, compute: |average confidence - actual accuracy|</li><li>Average across bins = Expected Calibration Error (ECE)</li></ul></li><li>Compare: Which model is better calibrated? Is the more accurate model also the better-calibrated one?</li></ol><p><strong>What you&#39;ll discover:</strong></p><p>Better accuracy does not imply better calibration. A model can be 75% accurate with excellent calibration (it &quot;knows what it doesn&#39;t know&quot;) while another model is 80% accurate but poorly calibrated (it&#39;s overconfident on the questions it gets wrong). For safety-critical applications, calibration matters as much as accuracy — sometimes more. A well-calibrated model lets you set meaningful confidence thresholds for automated decision-making.</p><hr><h3 id="exercise-4-the-comparison-lab" tabindex="-1">Exercise 4: The comparison lab <a class="header-anchor" href="#exercise-4-the-comparison-lab" aria-label="Permalink to &quot;Exercise 4: The comparison lab&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Open the <strong>Compare page</strong> in LLMxRay</li><li>Select a single model and use the <strong>Temperature Sweep</strong> preset, which configures three runs at temperatures 0.2, 0.7, and 1.2</li><li>Enter a creative prompt: <em>&quot;Write a haiku about artificial intelligence&quot;</em></li><li>Run the comparison and examine the <strong>ComparisonGrid</strong>: <ul><li>At 0.2: How does the output read? Is it predictable? Generic?</li><li>At 0.7: Is there more variety? Does it still make sense?</li><li>At 1.2: Is it creative or chaotic? Does it still follow the haiku structure (5-7-5)?</li></ul></li><li>Switch to the <strong>ComparisonDiffView</strong> to see exact word-level differences between pairs of outputs. How many words change between 0.2 and 0.7? Between 0.7 and 1.2?</li><li>Check the <strong>ComparisonMetricsBar</strong>: Does temperature affect generation speed or token count?</li><li>Now try the <strong>Deterministic Pair</strong> preset with the same seed but two different temperatures (e.g., 0.3 and 0.9). Run the haiku prompt again. Since the seed is fixed, any differences are purely due to temperature — not random sampling.</li><li>Finally, try a factual prompt: <em>&quot;What is the capital of Australia?&quot;</em> Does temperature affect factual accuracy, or only creative variation?</li></ol><p><strong>What you&#39;ll discover:</strong></p><p>Temperature is a precision tool, not a quality dial. Low temperature produces safe, predictable output — good for factual tasks, bland for creative ones. High temperature introduces diversity and surprise, but also incoherence and structural errors. The Deterministic Pair comparison proves that temperature alone — not random chance — drives the differences. And factual questions are largely temperature-invariant because the correct answer has overwhelming probability mass at any reasonable temperature. This is the bridge between Module 2&#39;s theory and real experimental evidence.</p><hr><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ol><li><strong>No model is universally best.</strong> Every model has a profile of strengths and weaknesses that the category-level breakdown reveals. Aggregate scores conceal more than they reveal.</li><li><strong>Benchmarks measure narrow slices.</strong> ARC tests science reasoning. TruthfulQA tests misconception resistance. MMLU-Pro tests breadth. No single benchmark captures &quot;intelligence&quot; — and running multiple benchmarks is essential for a complete picture.</li><li><strong>Calibration is as important as accuracy.</strong> A model that knows when it&#39;s uncertain is safer and more useful than one that&#39;s always confident. Real logprobs from SSE streaming give you ground-truth calibration data.</li><li><strong>Thinking models trade speed for accuracy.</strong> Chain-of-thought reasoning in <code>&lt;think&gt;</code> blocks can dramatically improve performance on reasoning tasks, but at a 5-10x latency cost. Dynamic token budgets ensure fair comparison.</li><li><strong>Controlled comparison is the scientific method applied to AI.</strong> Temperature sweeps, deterministic pairs, and side-by-side diffs let you isolate variables and draw causal conclusions — not just correlations from leaderboards.</li></ol><hr><h2 id="discussion-questions" tabindex="-1">Discussion Questions <a class="header-anchor" href="#discussion-questions" aria-label="Permalink to &quot;Discussion Questions&quot;">​</a></h2><ol><li>If you were choosing a model for a <strong>medical chatbot</strong>, which benchmarks would matter most? Would you prioritize accuracy, calibration, or speed? What additional evaluations beyond standard benchmarks would you want to run?</li><li>Why might a model&#39;s benchmark score <strong>not predict its real-world usefulness</strong>? Consider the differences between multiple-choice evaluation and open-ended conversation. What factors do benchmarks miss?</li><li>How do <strong>thinking models change the speed/accuracy tradeoff</strong>? In what applications is the extra reasoning time worthwhile, and in what applications is it unacceptable? Could you use a thinking model for hard questions and a standard model for easy ones?</li><li>Two models score identically on ARC (72%) but one is well-calibrated and the other is overconfident. <strong>Which would you deploy</strong>, and why? Does your answer change depending on the application?</li><li>Benchmark datasets are <strong>static and public</strong>. Model developers can (and do) optimize for them. How does this affect what benchmark scores actually mean? What would a better evaluation system look like?</li></ol><hr><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><h3 id="academic-papers" tabindex="-1">Academic Papers <a class="header-anchor" href="#academic-papers" aria-label="Permalink to &quot;Academic Papers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Paper</th><th>Authors</th><th>Year</th><th>Link</th></tr></thead><tbody><tr><td>Measuring Massive Multitask Language Understanding</td><td>Hendrycks et al.</td><td>2021</td><td><a href="https://arxiv.org/abs/2009.03300" target="_blank" rel="noreferrer">arXiv:2009.03300</a></td></tr><tr><td>Think you have Solved Question Answering? Try ARC</td><td>Clark et al.</td><td>2018</td><td><a href="https://arxiv.org/abs/1803.05457" target="_blank" rel="noreferrer">arXiv:1803.05457</a></td></tr><tr><td>HellaSwag: Can a Machine Really Finish Your Sentence?</td><td>Zellers et al.</td><td>2019</td><td><a href="https://arxiv.org/abs/1905.07830" target="_blank" rel="noreferrer">arXiv:1905.07830</a></td></tr><tr><td>Training Verifiers to Solve Math Word Problems (GSM8K)</td><td>Cobbe et al.</td><td>2021</td><td><a href="https://arxiv.org/abs/2110.14168" target="_blank" rel="noreferrer">arXiv:2110.14168</a></td></tr><tr><td>Chatbot Arena: An Open Platform for Evaluating LLMs</td><td>Zheng et al.</td><td>2023</td><td><a href="https://arxiv.org/abs/2403.04132" target="_blank" rel="noreferrer">arXiv:2403.04132</a></td></tr><tr><td>On Calibration of Modern Neural Networks</td><td>Guo, Pleiss, Sun, Weinberger</td><td>2017</td><td><a href="https://arxiv.org/abs/1706.04599" target="_blank" rel="noreferrer">arXiv:1706.04599</a></td></tr></tbody></table><h3 id="tutorials-and-resources" tabindex="-1">Tutorials and Resources <a class="header-anchor" href="#tutorials-and-resources" aria-label="Permalink to &quot;Tutorials and Resources&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Resource</th><th>Description</th><th>Link</th></tr></thead><tbody><tr><td>HuggingFace Open LLM Leaderboard</td><td>Live rankings of open models across standard benchmarks</td><td><a href="https://huggingface.co/spaces/open-llm-leaderboard/open_llm_leaderboard" target="_blank" rel="noreferrer">huggingface.co/spaces/open-llm-leaderboard</a></td></tr><tr><td>LLMxRay Benchmark Documentation</td><td>Guide to running and interpreting benchmarks in LLMxRay</td><td><a href="/llmxray/docs/en/guide/benchmark.html">LLMxRay Docs</a></td></tr><tr><td>LMSYS Chatbot Arena Leaderboard</td><td>Elo-based rankings from human preference votes</td><td><a href="https://chat.lmsys.org/?leaderboard" target="_blank" rel="noreferrer">lmsys.org</a></td></tr></tbody></table><hr><h2 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h2><p><strong>Option A — Benchmark analysis report (individual, 2 pages):</strong> Select two models and run at least two benchmarks (ARC + one other) on each. Produce a written report that includes: overall accuracy comparison, per-category heatmap analysis, calibration error calculation for both models, latency comparison, and a final recommendation — which model would you choose for a specific use case (you define the use case), and why? Support every claim with data from your LLMxRay experiments.</p><p><strong>Option B — Comparison presentation (pairs, slide deck):</strong> Design a 6-10 slide presentation that walks through a controlled experiment using the Compare page. Your experiment must isolate one variable (model, temperature, or system prompt) while holding others constant. Show side-by-side outputs, diff views, and metrics. Conclude with: what did you learn about this variable&#39;s effect, and how would this inform real-world model deployment?</p><p><strong>Option C — Model selection committee (groups of 3-4, role play):</strong> Your group is the AI evaluation team at a company choosing a model for customer support. Each team member advocates for a different model based on their benchmark data. Present your cases, debate the tradeoffs (accuracy vs speed vs calibration vs cost), and produce a one-page consensus recommendation with dissenting opinions noted. The recommendation must reference specific benchmark categories and comparison results.</p><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><p>In <strong><a href="./module-8.html">Module 8: The Full Picture</a></strong>, you&#39;ll step back from individual models and look at the broader landscape. How can your benchmark data and observations contribute to the open-source research community? You&#39;ll learn about reproducibility, result sharing, and how local experimentation with tools like LLMxRay connects to the global effort to understand and improve language models.</p><hr><div style="background:rgba(168,85,247,0.06);border-radius:8px;padding:1rem 1.5rem;margin-top:2rem;font-size:0.9rem;color:var(--vp-c-text-2);"><p><strong>Module 7 of 8</strong> in the LLMxRay Educators Kit <a href="./module-6.html">← Module 6: How Do Models Learn From Documents?</a> | <a href="./index.html">Back to Curriculum</a> | <a href="./module-8.html">Module 8: The Full Picture →</a></p></div>',89)])])}const f=t(l,[["render",c]]);export{b as __pageData,f as default};
